sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }
    if (!newValue == '') {
        g_form.setSectionDisplay('device_details', true);
        g_form.setSectionDisplay('delivery_details', true);

        //if somone put the device name (field name), get the details about it. then the call back fuunction, we named it getDetails.
        g_form.getReference('u_reference_2', getDetails); //we decieared the get reference
    }
    //here we need to call the. callback function
    function getDetails(details) { //in ( ) can be any name as variable.
        g_form.setValue('u_string_3', details.model_number);
        g_form.setValue('u_string_4', details.short_description);
        g_form.setValue('u_price_5', details.u_price_2);
        g_form.setValue('u_glide_date_7', details.warranty_expiration);
    }
}
